function statusBn(s){return ({active:'সক্রিয়',inactive:'নিষ্ক্রিয়',graduated:'উত্তীর্ণ',transferred:'স্থানান্তরিত',dropped_out:'ঝরে পড়া',retired:'অবসর',former:'সাবেক'})[s]||s||'—'}
